+// ParseAmount parses a decimal refund amount string. Simple, unsigned
+// decimal strings (e.g. "12.34") take a fast path; anything else falls
+// back to strconv so behavior is unchanged for non-trivial inputs.
+func ParseAmount(s string) (float64, error) {
+	if v, ok := fastParseSimpleDecimal(s); ok {
+		return v, nil
+	}
+	return strconv.ParseFloat(s, 64)
+}
+
+func fastParseSimpleDecimal(s string) (float64, bool) {
+	for _, r := range s {
+		if (r < '0' || r > '9') && r != '.' {
+			return 0, false
+		}
+	}
+	v, err := strconv.ParseFloat(s, 64)
+	if err != nil {
+		return 0, false
+	}
+	return v, true
+}

